#!/bin/bash

echo "Do publish estimate"
curl -k -X 'POST' \
   '${GRAPE_API_URL:-http://localhost:8010}/api/rest/transactions/estimate' \
   -H 'accept: application/json' \
   -H 'Authorization: Basic ${GRAPE_API_AUTH:?set GRAPE_API_AUTH (base64 user:pass)}'  \
   -H 'Content-Type: application/json' \
   -d '{
   "encodedTx": ""
}'

echo 'Do publish'

curl -k -X 'POST' \
   '${GRAPE_API_URL:-http://localhost:8010}/api/rest/transactions' \
   -H 'accept: application/json' \
   -H 'Authorization: Basic ${GRAPE_API_AUTH:?set GRAPE_API_AUTH (base64 user:pass)}'  \
   -H 'Content-Type: application/json' \
   -d '{
   "encodedTx": ""
}'

echo "Do SafeMint estimate"
curl -k -X 'POST' \
   '${GRAPE_API_URL:-http://localhost:8010}/api/rest/transactions/estimate' \
   -H 'accept: application/json' \
   -H 'Authorization: Basic ${GRAPE_API_AUTH:?set GRAPE_API_AUTH (base64 user:pass)}'  \
   -H 'Content-Type: application/json' \
   -d '{
   "encodedTx": ""
}'


echo "Do SafeMint"
curl -k -X 'POST' \
   '${GRAPE_API_URL:-http://localhost:8010}/api/rest/transactions' \
   -H 'accept: application/json' \
   -H 'Authorization: Basic ${GRAPE_API_AUTH:?set GRAPE_API_AUTH (base64 user:pass)}'  \
   -H 'Content-Type: application/json' \
   -d '{
   "encodedTx": ""
}'

echo "Check balance"

curl -k  -H 'Authorization: Basic ${GRAPE_API_AUTH:?set GRAPE_API_AUTH (base64 user:pass)}'  "${GRAPE_API_URL:-http://localhost:8010}/api/rest/contracts/0x70207524f48df8de24bfa557c5c1d27831d36afb/methods/0x70a08231?params=0x959cc0177d3cf38cb04104f40b1d66d05beb6edb&sender="

echo "Check balance ContractId"

curl -k  -H 'Authorization: Basic ${GRAPE_API_AUTH:?set GRAPE_API_AUTH (base64 user:pass)}'  "${GRAPE_API_URL:-http://localhost:8010}/api/rest/contracts/0x70207524f48df8de24bfa557c5c1d27831d36afb?params=0x70a08231000000000000000000000000959cc0177d3cf38cb04104f40b1d66d05beb6edb&sender=0x12aabc15ee"
